    {
      "rank": 1,
      "ballot_id": "B037",
      "proposed_laureates": [
        "Christopher Jarzynski",
        "Gavin E. Crooks",
        "Udo Seifert"
      ],
      "assessment": {
        "nobel_worthiness": "A major conceptual framework that gives precise, testable laws for fluctuations and work far from equilibrium, connecting microscopic reversibility to macroscopic thermodynamics.",
        "attribution": "Jarzynski's equality, Crooks's relation, and Seifert's stochastic thermodynamics are distinct central contributions. Evans's earlier fluctuation theorem is also foundational, so restricting the recognition to three people is difficult.",
        "maturity": "The framework has been tested in experiments and simulations and now informs work across statistical physics, chemistry, and biology.",
        "uncertainties": [
          "The discovery is distributed across related results, and the relative weight of the early Evans theorem and later formulations is contestable."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B011",
      "proposed_laureates": [
        "David R. Nelson",
        "Bertrand I. Halperin",
        "A. Peter Young"
      ],
      "assessment": {
        "nobel_worthiness": "The theory of defect-mediated melting and the hexatic phase established a deep and influential account of how order changes in two dimensions.",
        "attribution": "Nelson, Halperin, and Young jointly developed the central theory; the contribution is unusually well suited to shared recognition.",
        "maturity": "The predictions have been examined in physical systems and simulations over decades, and the framework remains central to two-dimensional melting.",
        "uncertainties": [
          "The boundary between the original theoretical prediction and later experimental identification of the hexatic phase merits careful credit."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Michael V. Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov–Bohm effect and Berry phase reveal that quantum phases and gauge structure have observable consequences, with reach across quantum mechanics and condensed matter.",
        "attribution": "Aharonov's work established the physical significance of potentials and phase; Berry identified the general geometric phase in adiabatic evolution. These are related but distinguishable contributions.",
        "maturity": "Both effects have extensive experimental confirmation and remain standard tools for understanding quantum phenomena.",
        "uncertainties": [
          "The ballot groups two major discoveries whose histories and contributor lists are not identical."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Peter W. Shor",
        "Andrew M. Steane",
        "Alexei Kitaev"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed that quantum information can be protected despite noise and supplied the conceptual route to fault-tolerant quantum computation.",
        "attribution": "Shor and Steane independently introduced quantum error-correcting codes; Kitaev developed the topological approach to fault tolerance. The proposed trio captures complementary foundational steps.",
        "maturity": "The principles are experimentally implemented in increasingly capable quantum devices, although large-scale fault-tolerant computation remains a work in progress.",
        "uncertainties": [
          "The field has many important contributors, and the eventual scale and impact of fault-tolerant quantum computing remain unsettled."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B027",
      "proposed_laureates": [
        "Frank Wilczek",
        "Jan Myrheim",
        "Jon Magne Leinaas"
      ],
      "assessment": {
        "nobel_worthiness": "The recognition that particles in two dimensions can obey fractional exchange statistics changed the landscape of quantum theory and enabled later topological physics.",
        "attribution": "Leinaas and Myrheim gave an early systematic account of fractional statistics; Wilczek independently developed the anyon concept and its physical consequences.",
        "maturity": "The theoretical idea is established, and fractional exchange statistics have gained strong experimental support in quantum Hall systems.",
        "uncertainties": [
          "The credit for the original formulation and the later physical development is spread across different works and communities."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Peter G. Wolynes",
        "Ken A. Dill",
        "José N. Onuchic"
      ],
      "assessment": {
        "nobel_worthiness": "Energy landscape theory gave a physical framework for understanding how proteins fold reliably despite a vast configuration space, linking statistical mechanics to a central problem in biology.",
        "attribution": "Wolynes, Dill, and Onuchic made complementary contributions to the landscape picture and its application to protein folding.",
        "maturity": "The framework has guided extensive theoretical and experimental work, though protein-folding research now includes methods and advances beyond this original account.",
        "uncertainties": [
          "The scope of the prizeworthy discovery and the relative contributions of the three researchers would need careful delimitation."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Federico Capasso",
        "Alfred Y. Cho",
        "Jérôme Faist"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum cascade laser was a distinct device concept that opened important mid-infrared and terahertz applications and advanced semiconductor optoelectronics.",
        "attribution": "Capasso and Faist were central to the device concept and its demonstration, while Cho's semiconductor heterostructure expertise helped make the required layered structures possible.",
        "maturity": "The technology has been developed over decades and is used in spectroscopy, sensing, and other applications.",
        "uncertainties": [
          "Credit should distinguish the original device idea from the enabling materials-growth work and subsequent engineering."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation offers an influential account of the early universe and connects quantum fluctuations to the origin of cosmic structure.",
        "attribution": "Guth introduced the inflationary idea, Linde developed important viable versions, and Mukhanov derived a central account of primordial perturbations.",
        "maturity": "The framework is consistent with much cosmological evidence, but key features of inflation and its mechanism have not been directly established.",
        "uncertainties": [
          "The lack of a unique, directly confirmed inflationary model makes both the discovery claim and the timing of recognition uncertain."
        ]
      }
    }
  ]
}
